-- FROZEN SQL of migration 0005-g07-revised-article-evidence (M1 unified design, SELF_VALIDATED, WORK_REVIEW_PENDING, applied to no operational database).
-- Same file format as 0002 (a `requires` names tables that exist BEFORE the migration: it is evaluated once, before the first statement runs). G-07: the concrete evidence VERSIONS that a revised article cites become rows (until now only inside revised_articles.record_json). The relation is filled from the record by a
-- trigger (Work's finalize needs no change), every row is checked (the evidence exists, in the article's own case, and is a version, never an alias), the table is append-only and gated.
-- The backfill adds only what the existing records state AND the database can confirm; anything else stays out and is shown by v_revised_article_evidence_mismatch (no version is guessed, no old row is touched).
-- An article keeps citing the exact version it cited: nothing here ever reads the current head.
-- @@ requires: table revised_articles, table article_versions, table article_evidence, table facts, table evidence_revisions, table evidence_aliases
CREATE TABLE revised_article_evidence(
 article_id TEXT NOT NULL REFERENCES revised_articles(article_id), evidence_id TEXT NOT NULL, case_id TEXT NOT NULL,
 PRIMARY KEY(article_id, evidence_id))
-- @@ requires: table revised_articles, table article_versions, table article_evidence, table facts, table evidence_revisions, table evidence_aliases
INSERT OR IGNORE INTO revised_article_evidence(article_id, evidence_id, case_id) SELECT r.article_id, j.value, v.case_id FROM revised_articles r JOIN article_versions v ON v.article_id = r.base_article_id, json_each(json_extract(r.record_json, '$.evidence_ids')) j WHERE (EXISTS(SELECT 1 FROM facts f WHERE f.evidence_id = j.value AND f.case_id = v.case_id) OR EXISTS(SELECT 1 FROM evidence_revisions e WHERE e.evidence_id = j.value AND e.case_id = v.case_id)) AND NOT EXISTS(SELECT 1 FROM evidence_aliases a WHERE a.alias_id = j.value)
-- @@ requires: table revised_articles, table article_versions, table article_evidence, table facts, table evidence_revisions, table evidence_aliases
CREATE TRIGGER trg_rae_evidence_exists BEFORE INSERT ON revised_article_evidence WHEN NOT EXISTS(SELECT 1 FROM facts WHERE evidence_id = NEW.evidence_id AND case_id = NEW.case_id) AND NOT EXISTS(SELECT 1 FROM evidence_revisions WHERE evidence_id = NEW.evidence_id AND case_id = NEW.case_id) BEGIN SELECT RAISE(ABORT, 'cited evidence is unknown or belongs to another case'); END
-- @@ requires: table revised_articles, table article_versions, table article_evidence, table facts, table evidence_revisions, table evidence_aliases
CREATE TRIGGER trg_rae_article_case BEFORE INSERT ON revised_article_evidence WHEN NOT EXISTS(SELECT 1 FROM revised_articles r JOIN article_versions v ON v.article_id = r.base_article_id WHERE r.article_id = NEW.article_id AND v.case_id = NEW.case_id) BEGIN SELECT RAISE(ABORT, 'the revised article is unknown or belongs to another case'); END
-- @@ requires: table revised_articles, table article_versions, table article_evidence, table facts, table evidence_revisions, table evidence_aliases
CREATE TRIGGER trg_rae_not_an_alias BEFORE INSERT ON revised_article_evidence WHEN EXISTS(SELECT 1 FROM evidence_aliases WHERE alias_id = NEW.evidence_id) BEGIN SELECT RAISE(ABORT, 'a citation names a concrete evidence version, never an alias'); END
-- @@ requires: table revised_articles, table article_versions, table article_evidence, table facts, table evidence_revisions, table evidence_aliases
CREATE TRIGGER trg_rae_append_only_update BEFORE UPDATE ON revised_article_evidence BEGIN SELECT RAISE(ABORT, 'revised_article_evidence is append-only'); END
-- @@ requires: table revised_articles, table article_versions, table article_evidence, table facts, table evidence_revisions, table evidence_aliases
CREATE TRIGGER trg_rae_append_only_delete BEFORE DELETE ON revised_article_evidence BEGIN SELECT RAISE(ABORT, 'revised_article_evidence is append-only'); END
-- @@ requires: table revised_articles, table article_versions, table article_evidence, table facts, table evidence_revisions, table evidence_aliases
CREATE TRIGGER trg_gate_revised_article_evidence_insert BEFORE INSERT ON revised_article_evidence BEGIN SELECT sogh_write_ok(); END
-- @@ requires: table revised_articles, table article_versions, table article_evidence, table facts, table evidence_revisions, table evidence_aliases
CREATE TRIGGER trg_rae_fill AFTER INSERT ON revised_articles BEGIN INSERT INTO revised_article_evidence(article_id, evidence_id, case_id) SELECT NEW.article_id, j.value, (SELECT v.case_id FROM article_versions v WHERE v.article_id = NEW.base_article_id) FROM json_each(json_extract(NEW.record_json, '$.evidence_ids')) j; END
-- @@ requires: table revised_articles, table article_versions, table article_evidence, table facts, table evidence_revisions, table evidence_aliases
CREATE VIEW v_article_citations AS SELECT a.article_id, 'base' AS article_kind, a.evidence_id, r.root_evidence_id FROM article_evidence a JOIN v_evidence_root r ON r.evidence_id = a.evidence_id UNION ALL SELECT a.article_id, 'revised', a.evidence_id, r.root_evidence_id FROM revised_article_evidence a JOIN v_evidence_root r ON r.evidence_id = a.evidence_id
-- @@ requires: table revised_articles, table article_versions, table article_evidence, table facts, table evidence_revisions, table evidence_aliases
CREATE VIEW v_revised_article_evidence_mismatch AS SELECT r.article_id, 'in_record_not_in_relation' AS kind, j.value AS evidence_id FROM revised_articles r, json_each(json_extract(r.record_json, '$.evidence_ids')) j WHERE NOT EXISTS(SELECT 1 FROM revised_article_evidence e WHERE e.article_id = r.article_id AND e.evidence_id = j.value) UNION ALL SELECT e.article_id, 'in_relation_not_in_record', e.evidence_id FROM revised_article_evidence e JOIN revised_articles r ON r.article_id = e.article_id WHERE e.evidence_id NOT IN (SELECT value FROM json_each(json_extract(r.record_json, '$.evidence_ids')))
